func runServicesIteration(
	ctx context.Context,
	opts RunServicesOptions,
	forwardedPorts []string,
	resolver PortAttributeResolver,
) error {
	stdoutReader, stdoutWriter, err := os.Pipe()
	if err != nil {
		return err
	}
	defer func() { _ = stdoutWriter.Close() }()

	stdinReader, stdinWriter, err := os.Pipe()
	if err != nil {
		_ = stdoutReader.Close()
		return err
	}
	defer func() { _ = stdinReader.Close() }()

	cancelCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	forwarder := createForwarder(opts, forwardedPorts, resolver)

	errChan := make(chan error, 1)
	go runTunnelServer(cancelCtx, cancel, tunnelServerParams{
		opts:         opts,
	defer runGPGTunnelInBackground(ctx, gpgTunnel, toolSSHClient)()

	// Handle ssh stdio mode
	if cmd.Stdio {
		if cmd.SSHKeepAliveInterval != DisableSSHKeepAlive {
			go startSSHKeepAlive(ctx, toolSSHClient, cmd.SSHKeepAliveInterval)
		}

		return client.DirectTunnel(ctx, os.Stdin, os.Stdout)
	}

